{
  "status": "SUPPORTED",
  "task_summary": "Locate fastening components, perform the fastening on the workbench, and return the tool.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "fastening_target",
        "entity_kind": "OBJECT",
        "function": "The object or assembly located at the specified workbench spot that requires securing.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "assembly",
          "part",
          "workpiece"
        ],
        "required_properties": [
          "has_connection_points",
          "requires_fastening"
        ]
      },
      {
        "id": "fastener",
        "entity_kind": "OBJECT",
        "function": "The hardware component (screw, bolt, etc.) used to join or secure the target.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "screw",
          "bolt",
          "nut",
          "pin"
        ],
        "required_properties": [
          "fits_target",
          "drivable"
        ]
      },
      {
        "id": "tool",
        "entity_kind": "OBJECT",
        "function": "The implement used to apply force to install the fastener.",
        "required_count": 1,
        "binding_policy": "DISTINCT",
        "candidate_categories": [
          "screwdriver",
          "wrench",
          "driver"
        ],
        "required_properties": [
          "drives_fastener_type"
        ]
      },
      {
        "id": "workbench",
        "entity_kind": "REGION",
        "function": "The surface where the task is performed and where tools are returned.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "table",
          "desk",
          "surface"
        ],
        "required_properties": [
          "is_stable",
          "supports_objects"
        ]
      },
      {
        "id": "storage",
        "entity_kind": "REGION",
        "function": "Enclosed spaces containing potential components.",
        "required_count": 2,
        "binding_policy": "SHARED",
        "candidate_categories": [
          "drawer",
          "cabinet",
          "bin"
        ],
        "required_properties": [
          "has_interior_volume",
          "is_accessible"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "compatible_fastener",
        "relation": "fits",
        "participant_roles": [
          "fastener",
          "fastening_target"
        ]
      ,
        "required": true
      },
      {
        "id": "effective_tool",
        "relation": "operates_on",
        "participant_roles": [
          "tool",
          "fastener"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "inspect_storage",
        "operation": "open_and_search",
        "participant_roles": [
          "storage"
        ,
          "robot"
        ]
      ,
        "operation_count": 2
      },
      {
        "id": "fasten",
        "operation": "drive_fastener",
        "participant_roles": [
          "tool",
          "fastener",
          "fastening_target"
        ]
      ,
        "operation_count": 1
      },
      {
        "id": "place_tool",
        "operation": "set_down",
        "participant_roles": [
          "tool",
          "workbench"
        ]
      ,
        "operation_count": 1
      }
    ]
  }
,
  "observation_guidance": {
    "visible_candidates_per_role": {
      "fastening_target": [
        {
          "label": "yellow_and_blue_block",
          "visual_description": "A small rectangular object with yellow and blue coloring sitting on a dark mat on the table surface."
        }
      ],
      "fastener": [],
      "tool": [],
      "workbench": [
        {
          "label": "wooden_table",
          "visual_description": "A wooden desk with two drawers underneath and a flat top surface."
        }
      ],
      "storage": [
        {
          "label": "under_table_drawers",
          "visual_description": "Two blue drawers located beneath the left side of the wooden table."
        },
        {
          "label": "tall_cabinet",
          "visual_description": "A tall blue cabinet standing against the wall behind the table."
        }
      ]
    },
    "inspectable_regions": [
      {
        "id": "under_table_drawers",
        "label": "under_table_drawers",
        "visual_description": "Two blue drawers located beneath the left side of the wooden table.",
        "reason": "Likely contains small hardware components or tools given the context of a workbench setup."
      },
      {
        "id": "tall_cabinet",
        "label": "tall_cabinet",
        "visual_description": "A tall blue cabinet standing against the wall behind the table.",
        "reason": "Standard storage unit for larger tools or supplies in this environment."
      }
    ],
    "inspection_order": [
      "under_table_drawers",
      "tall_cabinet"
    ]
  }
,
